RECORDS = []


def pytest_runtest_logreport(report):
    if "test_goal_" not in report.nodeid:
        return
    if report.when == "call" or (report.when == "setup" and report.outcome != "passed"):
        match = re.search(r"test_goal_(\d+)_", report.nodeid)
        status = ("xfail" if hasattr(report, "wasxfail") else
                  "blocked" if report.outcome == "skipped" or report.when == "setup" else
                  report.outcome)
        RECORDS.append({"goal": int(match.group(1)), "test": report.nodeid,
                        "status": status, "reason": str(getattr(report, "wasxfail", ""))})


def pytest_sessionfinish(session, exitstatus):
    destination = session.config.getoption("--goal-scorecard")
    if not destination:
        return
    path = Path(destination)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render_scorecard(RECORDS, exitstatus), encoding="utf-8")


@pytest.fixture(scope="session", autouse=True)
def offline_boundary():
    with pytest.MonkeyPatch.context() as patch:
        for name in list(os.environ):
            if name == "OPENAI_API_KEY" or name.startswith(("PO_BACKEND_", "PG")):
                patch.delenv(name, raising=False)
        original_open, original_os_open = builtins.open, os.open

        def guard_path(path):
            if isinstance(path, (str, bytes, os.PathLike)):
                name = Path(os.fsdecode(path)).name.casefold()
                if name.startswith(".env"):
                    raise RuntimeError("goal tests must never open dotenv files")

        def safe_open(path, *args, **kwargs):
            guard_path(path)
            return original_open(path, *args, **kwargs)

        def safe_os_open(path, *args, **kwargs):
            guard_path(path)
            return original_os_open(path, *args, **kwargs)

        def forbidden(*args, **kwargs):
            raise RuntimeError("goal tests forbid built-in providers and external HTTP")

        patch.setattr(builtins, "open", safe_open)
        patch.setattr(io, "open", safe_open)
        patch.setattr(os, "open", safe_os_open)
        patch.setattr(OpenAIProvider, "extract", forbidden)
        patch.setattr(SyntheticProvider, "extract", forbidden)
        patch.setattr(httpx.HTTPTransport, "handle_request", forbidden)
        patch.setattr(httpx.AsyncHTTPTransport, "handle_async_request", forbidden)
        yield


@pytest.fixture(scope="session")
def goal_engine(tmp_path_factory, offline_boundary):
    from tests.isolated_postgres import owned_database, owned_postgres
    scratch = tmp_path_factory.mktemp("postgres")
    try:
        with owned_postgres(scratch, ROOT) as admin_url, owned_database(admin_url) as engine:
            config = Config(str(ROOT / "backend.alembic.ini"))
            with engine.begin() as connection:
                config.attributes["connection"] = connection
                command.upgrade(config, "head")
            yield engine
    except FileNotFoundError as error:
        if os.environ.get("GITHUB_ACTIONS") == "true":
            pytest.fail(str(error))
        pytest.skip("BLOCKED: " + str(error))


class FixedJSONProvider:
    model = "fixed-json-goal-fixture"
    prompt_version = "hand-authored-goal-v1"
    schema_version = "1.1"

    def __init__(self):
        self.json_text = ""
        self.calls = []

    def set_payload(self, value):
        self.json_text = json.dumps(deepcopy(value))

    def extract(self, source_bytes, media_type, page_count, fixture_name=None):
        self.calls.append((source_bytes, media_type, page_count))
        return ProviderResult(payload=ExtractionPayload.model_validate(json.loads(self.json_text)),
                              state="succeeded", model=self.model, prompt_version=self.prompt_version,
                              schema_version=self.schema_version, synthetic=True, usage={})


